// 模拟 OpenClaw 获取最新未读微信消息接口
app.get('/api/wechat/openclaw/messages', (req, res) => {
  const limit = parseInt(req.query.limit) || 20;
  console.log(`[OpenClaw] Fetching last ${limit} WeChat messages...`);

  res.json([
    { from_user: "张经理 (昆仑2群)", content: "帅总，我们最近的小红书起号遇到了卡点，转化率突然从4%跌到了1%，这周有时间帮我们做个诊断吗？预算大概有2万左右。", timestamp: new Date(Date.now() - 600000).toISOString(), is_group: true },
    { from_user: "李总 (私聊)", content: "你好，请问你们的智能体交付标准手册在哪里下载？我已经支付了会员费。", timestamp: new Date(Date.now() - 3600000).toISOString(), is_group: false },
    { from_user: "王五 (昆仑5群)", content: "这套AI系统太牛逼了！帮我们省了3个人力。", timestamp: new Date(Date.now() - 7200000).toISOString(), is_group: true }
  ]);
});

